package com.leapfrog.leapfrog.exception;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;

import java.util.HashMap;
import java.util.Map;

@ControllerAdvice
public class LeapFrogExceptionHandler {

    @ExceptionHandler(LeapFrogException.class)
    public ResponseEntity<Map<String, String>> handleLeapFrogException(LeapFrogException ex) {
        Map<String, String> body = new HashMap<>();
        body.put("error", ex.getMessage());
        return new ResponseEntity<>(body, ex.getStatus());
    }
}
